import styles from "./Users.module.css";
import userPhoto from "../../assets/images/defaultUser.jpg";
import {NavLink} from "react-router-dom";

const User = ({ user, isLockedButtons, unfollow, follow }) => {

    return (
        <div>   
            <span>
                <div>
                    <NavLink to={"/profile/" + user.id}>
                        <img src={user.photos.small != null ? user.photos.small : userPhoto}
                             className={styles.userPhoto}/>
                    </NavLink>
                </div>
                <div>
                    {user.followed
                        ? <button disabled={isLockedButtons.some(id => id === user.id)} onClick={() => {
                            unfollow(user.id);
                        }}>Unfollow</button>
                        : <button disabled={isLockedButtons.some(id => id === user.id)} onClick={() => {
                            follow(user.id);
                        }}>Follow</button>}
                </div>
            </span>
            <span>
                <span>
                    <div>{user.name}</div>
                    <div>{user.status}</div>
                </span>
                <span>
                    <div>Moscow</div>
                    <div>Russia</div>
                </span>
            </span>
        </div>
    )

}

export default User;